<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ویرایش محصول | مدیریت گره</title><link rel="stylesheet" href="<?= base_url('assets/css/app.css') ?>"><style>body{font-family:Tahoma,sans-serif;background:#f5f5f2;color:#012f24;margin:0}.wrap{max-width:920px;margin:auto;padding:24px}a{color:#075d3c}.panel{background:#fff;border-radius:14px;padding:24px;margin:20px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}label{display:block;font-size:13px;margin-bottom:12px}input,select,textarea{display:block;width:100%;box-sizing:border-box;border:1px solid #ddd;border-radius:9px;padding:12px;margin-top:7px;font:inherit}textarea{min-height:130px}button{background:#012f24;color:white;padding:13px 24px;border:0;border-radius:9px;cursor:pointer}.error{background:#fff0ec;padding:12px;border-radius:8px}.success{background:#e7f1ec;padding:12px;border-radius:8px}table{width:100%;border-collapse:collapse}td,th{padding:12px;border-bottom:1px solid #eee;text-align:right}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><a href="<?= site_url('admin/products') ?>">← بازگشت به محصولات</a><h1><?= $product ? 'ویرایش محصول' : 'محصول جدید' ?></h1><?php if(session()->getFlashdata('errors')): ?><div class="error" role="alert"><?php foreach((array)session()->getFlashdata('errors') as $error): ?><p><?= esc($error) ?></p><?php endforeach; ?></div><?php endif; ?><?php if(session()->getFlashdata('success')): ?><p class="success"><?= esc(session()->getFlashdata('success')) ?></p><?php endif; ?><section class="panel"><form action="<?= $product ? site_url('admin/products/'.$product['id'].'/edit') : site_url('admin/products/create') ?>" method="post"><?= csrf_field() ?><div class="grid"><label>نام محصول<input required name="name" maxlength="220" value="<?= esc(old('name',$product['name']??''),'attr') ?>"></label><label>نشانی انگلیسی (slug)<input required name="slug" pattern="[a-z0-9-]+" maxlength="220" value="<?= esc(old('slug',$product['slug']??''),'attr') ?>"></label><label>قیمت (تومان)<input type="number" min="0" required name="price_toman" value="<?= esc((string)old('price_toman',$product['price_toman']??0),'attr') ?>"></label><label>وضعیت<select name="status"><option value="draft">پیش‌نویس</option><option value="active" <?= old('status',$product['status']??'')==='active'?'selected':'' ?>>فعال</option><option value="archived" <?= old('status',$product['status']??'')==='archived'?'selected':'' ?>>بایگانی</option></select></label><label>دسته‌بندی<select name="category_id"><option value="">بدون دسته</option><?php foreach($categories as $item): ?><option value="<?= (int)$item['id'] ?>" <?= (string)old('category_id',$product['category_id']??'')===(string)$item['id']?'selected':'' ?>><?= esc($item['name']) ?></option><?php endforeach; ?></select></label><label>برند<select name="brand_id"><option value="">بدون برند</option><?php foreach($brands as $item): ?><option value="<?= (int)$item['id'] ?>" <?= (string)old('brand_id',$product['brand_id']??'')===(string)$item['id']?'selected':'' ?>><?= esc($item['name']) ?></option><?php endforeach; ?></select></label></div><label>توضیح کوتاه<textarea name="short_description"><?= esc(old('short_description',$product['short_description']??'')) ?></textarea></label><label>توضیحات کامل<textarea name="description"><?= esc(old('description',$product['description']??'')) ?></textarea></label><button type="submit">ذخیره محصول</button></form></section><?php if($product): ?><section class="panel"><h2>تنوع‌های محصول</h2><table><thead><tr><th>SKU</th><th>سایز</th><th>رنگ</th></tr></thead><tbody><?php foreach($variants as $v): ?><tr><td><?= esc($v['sku']) ?></td><td><?= esc($v['size_label']??'—') ?></td><td><?= esc($v['color_name']??'—') ?></td></tr><?php endforeach; ?></tbody></table><h3>افزودن تنوع</h3><form method="post" action="<?= site_url('admin/products/'.$product['id'].'/variants') ?>"><?= csrf_field() ?><div class="grid"><label>SKU<input required name="sku" maxlength="80"></label><label>سایز<input name="size_label" maxlength="60"></label><label>رنگ<input name="color_name" maxlength="80"></label><label>موجودی اولیه<input required type="number" min="0" name="quantity" value="0"></label></div><button type="submit">ثبت تنوع و موجودی</button></form></section><?php endif; ?></main></body></html>